package com.example

import com.example.ExamQuestionHelper.QSpec

object DancingLiveExamKandyanCoreBank1 {
    private const val T = "උඩරට නර්තන සම්ප්‍රදාය, වෙස් ඇඳුම හා සරඹ"
    private fun q(stem: String, c: String, d1: String, d2: String, d3: String, exp: String) =
        QSpec(T, stem, c, listOf(d1, d2, d3), exp)

    fun questions(): List<QSpec> = listOf(
        q("උඩරට නර්තන සම්ප්‍රදායේ ආරම්භක ශිෂ්‍යයා පුහුණු වන මූලික ඉරියව්ව කුමක්ද?", "මණ්ඩි ඉරියව්ව", "සමපාද ඉරියව්ව", "ත්‍රිභංග ඉරියව්ව", "ආයත ඉරියව්ව", "දෙපා දෙපසට විහිදා දණහිස් නමා කඳ කෙළින් තබා ගන්නා මණ්ඩි ඉරියව්ව උඩරට නැටුමේ පදනමයි."),
        q("උඩරට නර්තන පුහුණුවේදී දණ්ඩියම් කඳ අල්ලාගෙන කරනු ලබන මූලික පාද අභ්‍යාස ගණන කීයද?", "පා සරඹ දොළහකි (12)", "පා සරඹ අටකි (8)", "පා සරඹ විස්සකි (20)", "පා සරඹ පහකි (5)", "පා සරඹ 12 ප්‍රගුණ කිරීමෙන් දෙපාවල සමබරතාව හා ශක්තිය වර්ධනය වේ."),
        q("දණ්ඩියම නොමැතිව හිස් අවකාශයේ අත් හා පාද චලන සමඟ පුහුණු වන උඩරට සරඹ කොටස කුමක්ද?", "ගොඩ සරඹ දොළහ (12)", "මුහුදු සරඹ දොළහ", "වන්නම් සරඹ හත", "තෙල්මේ සරඹ හතර", "පා සරඹ 12 අවසන් කළ පසු අත් චලන සමඟ ගොඩ සරඹ 12 පුහුණු කෙරේ."),
        q("උඩරට සරඹ පුහුණුවේදී පළමු පා සරඹය සඳහා යොදා ගන්නා පද මාලාව කුමක්ද?", "තත් ජිත් තොං නං", "දොං ජිං ජිං තකට", "කිටි තක දොං දොං", "හරි හරි තක තරි", "සරලව වම් හා දකුණු පාද මාරු කරමින් 'තත් ජිත් තොං නං' පදයට පළමු පා සරඹය නටයි."),
        q("උඩරට පා සරඹ අභ්‍යාසවලදී 'තත් තත් ජිත් ජිත් තොං තොං නං නං' යනු කීවෙනි පා සරඹයේ පද මාලාවද?", "දෙවන පා සරඹය", "හයවන පා සරඹය", "දසවන පා සරඹය", "දොළොස්වන පා සරඹය", "දෙපා දෙවර බැගින් තබා පුහුණු වීම දෙවන පා සරඹයේ ලක්ෂණයකි."),
        q("උඩරට නර්තන සම්ප්‍රදායේ ප්‍රධානතම සහ ගෞරවනීයම බෙරය කුමක්ද?", "ගැටබෙරය", "යක් බෙරය", "දිගු දවුල", "තම්මැට්ටම", "උඩරට මඟුල් බෙරය ලෙසින්ද හැඳින්වෙන ගැටබෙරය වෙස් නැටුමේ ප්‍රධාන වාද්‍ය භාණ්ඩයයි."),
        q("උඩරට වෙස් නැට්ටුවාගේ හිසේ පළඳින 'ශිඛා බන්ධනය' හෙවත් ජටාවෙහි මුදුනේ ඇති තුන් හුලස් කොටස කුමක්ද?", "සිළුමිණ හෝ මුදුන් මල්කඩ", "ඉනහැඩය", "සිළම්බු", "අවුල්හැරය", "ජටාව මුදුනේ ඇති මෙම කොටස මලය රජුගේ කිරුළ සංකේතවත් කරයි."),
        q("වෙස් තට්ටුව දෙපස කන් මත එල්ලා තබන දිලිසෙන අර්ධ වෘත්තාකාර ආභරණය කුමක්ද?", "තෝඩු යුගලය", "බුබුළු පටිය", "කරපටිය", "බඳ පටිය", "කන් වසා පළඳින රිදී හෝ පිත්තල තෝඩු යුගලය වෙස් මුහුණට ගාම්භීර පෙනුමක් දෙයි."),
        q("උඩරට වෙස් නැට්ටුවාගේ උරහිසේ සිට පපුව හරහා පළඳින පබළු ජාලමය ආභරණය කුමක්ද?", "අවුල්හැරය", "සිළම්බු", "ජටාව", "කලිසම", "සුදු, රතු හා නිල් වීදුරු පබළු ගොතා සාදන අවුල්හැරය උඩුකය අලංකාර කරයි."),
        q("වෙස් කට්ටලයේදී දෙඅත්වල උඩු බාහුවල පළඳින දඟර ආකාරයේ රිදී පැහැති ආභරණ යුගලය කුමක්ද?", "කයිමෙත්ත හෝ බාහු වළලු", "පා සළඹ", "හවඩිය", "මුදුන් පත", "නැට්ටුවාගේ උඩු බාහු ශක්තිමත් බව හා අලංකාරය වැඩි කිරීමට බාහු වළලු පළඳියි."),
        q("වෙස් නැට්ටුවාගේ ඉණෙහි බඳින ප්‍රධාන ආධාරක රිදී හා රතු පැහැති පටිය කුමක්ද?", "ඉනහැඩය හා බඳ පටිය", "අවුල්හැරය", "නළල් පටිය", "තෝඩු පටිය", "සුදු රෙද්ද හා රැළි මාලය ස්ථිරව රඳවා ගැනීමට ඉනහැඩය තදින් බඳිනු ලැබේ."),
        q("වෙස් ඇඳුමේ පහළ කොටසේ ඉදිරියෙන් එල්ලා වැටෙන අලංකාර ත්‍රිකෝණාකාර රැළි කොටස හඳුන්වන්නේ කුමන නමකින්ද?", "උළුදය හෙවත් දැති රැල්ල", "නළල් පටිය", "කරපටිය", "බුබුළු පටිය", "හංස පූට්ටු මෝස්තර සහිතව සුදු හා රතු රෙදිවලින් උළුදය නිමවා ඇත."),
        q("වෙස් තට්ටුවේ නළල මත හිඳුවන දීප්තිමත් රිදී හෝ පිත්තල ආභරණය කුමක්ද?", "නළල් පටිය හා බුබුළු පටිය", "සිළම්බු යුගලය", "උළුදය", "අත් වළලු", "මුහුණට තේජස ගෙන දෙන නළල් පටිය සමඟ කුඩා බෝල රැසක් එල්ලා ඇත."),
        q("වෙස් නැට්ටුවෙකු සැරසෙන සම්පූර්ණ වෙස් ආභරණ ප්‍රමාණය සාම්ප්‍රදායිකව හඳුන්වනු ලබන්නේ කුමන සංඛ්‍යාවකින්ද?", "සූසැට (64) ආභරණ ලෙස", "දොළොස් ආභරණ ලෙස", "අට ආභරණ ලෙස", "පන්සීය ආභරණ ලෙස", "වෙස් කට්ටලය රාජකීය සූසැට ආභරණවලින් සමන්විත පූජනීය ඇඳුමක් ලෙස සැලකේ."),
        q("උඩරට නර්තනයේදී වෙස් තට්ටුව මත පිහිටි රිදී කොළ හැඩති පත් හත හෝ නවය මගින් සංකේතවත් කරන්නේ කුමක්ද?", "බෝ පත්‍ර හා රාජකීය කිරුළ", "නෙළුම් මල් පෙති", "මොනර පිල්", "වී කරල්", "වෙස් තට්ටුවේ පත් මෝස්තර බෝ පත් හා නාග පෙන ආකෘතියෙන් නිමවා තිබේ."),
        q("ආධුනික උඩරට නර්තන ශිල්පියෙකුට වෙස් තට්ටුව පළඳවනු ලබන පූජනීය උත්සවය කුමක්ද?", "වෙස් මංගල්‍යය", "දහඅට සන්නිය", "රට යකුම", "පහන් මඩුව", "වසර ගණනාවක් පුහුණු වූ පසු දේවාලයකදී හෝ කංකාරි මඩුවකදී වෙස් මංගල්‍යය පවත්වයි."),
        q("වෙස් ඇඳුම් කට්ටලයේ පහළ කොටසට පළඳින දිගු සුදු රෙද්ද අඳින සම්ප්‍රදායික ක්‍රමය කුමක්ද?", "කච්ච ගසා උල්පට වශයෙන් නැමීම", "සරමක් මෙන් පහළට දැමීම", "දිග කලිසමක් ලෙස ඇඳීම", "වටා ඔතා ගැටගැසීම", "වේගවත් පිනුම් හා මණ්ඩි චලන සඳහා පහසු වන ලෙස කච්ච ගසා රැළි තබා අඳියි."),
        q("උඩරට නැටුමේදී ශිල්පියාගේ දෙඅත්වල මැණික් කටුව අසල පළඳින ආභරණ කුමක්ද?", "හස්ත කඩු හෙවත් අත් වළලු", "කරපටිය", "පා සළඹ", "තෝඩු", "බාහු වළලු හා මැණික් කටුව අසල පළඳින අත් වළලු දෙඅත් චලන අලංකාර කරයි."),
        q("උඩරට නර්තනයේ 'ගොඩ සරඹ' අභ්‍යාස මාලාවේ ප්‍රධානතම අරමුණ කුමක්ද?", "දෑත් සහ දෙපා එකවර රිද්මයට හා තාලයට සම්බන්ධීකරණය කිරීම", "කවි රචනා කිරීම පමණක් පුහුණු වීම", "වෙස්මුහුණු කැපීම ඉගෙන ගැනීම", "බෙර හම් පදම් කිරීම ඉගෙන ගැනීම", "හිස, ඇස්, අත් හා පාද අතර සමබර සම්බන්ධීකරණය ගොඩ සරඹවලින් ඇති කෙරේ."),
        q("උඩරට සම්ප්‍රදායේ 'වට්ටම් නැටීම' හෝ 'මණ්ඩි අඩව්' කුමන අවස්ථාවකදී ප්‍රධාන වේද?", "වෙස් නැටුමේ සහ වන්නම්වල අවසාන කොටසේදී", "පළමු පා සරඹයේ ආරම්භයේදී", "බෙර වාදනය නැවැත්වූ පසු", "වේදිකාවෙන් බැස යන විට", "නැටුමක කූටප්‍රාප්තිය පෙන්වීමට වේගවත් තීර්මාන හා අඩව් නටනු ලැබේ."),
        q("උඩරට නර්තන සම්ප්‍රදායේ එන 'නෛයන්ඩි' නැටුම බහුලව ඉදිරිපත් කරනු ලබන ශාන්තිකර්ම අවස්ථාව කුමක්ද?", "කොහොඹා කංකාරියේ සැන්දෑ පූජා අවස්ථාවේදී", "දහඅට සන්නියේ උදෑසන කොටසේදී", "සොකරි නාටකයේ අවසානයේදී", "කෝලම් රංගනයේ මුලදී", "සාමාන්‍යයෙන් දෙවියන් පිදීමේ කංකාරි ආරම්භක අංගවලදී නෛයන්ඩි නැටුම ඉදිරිපත් වේ."),
        q("උඩරට 'උඩැක්කි' නැටුමෙහි නැට්ටුවා සතු විශේෂ කුසලතාව කුමක්ද?", "තමා විසින්ම උඩැක්කිය වයමින් කවි ගයා නැටීම", "අනෙක් අයගේ බෙර අතින් ගෙන යාම", "වෙස්මුහුණු දෙකක් පැළඳීම", "වචන නොකියා නිහඬව සිටීම", "උඩැක්කි ශිල්පියා ගායනය, වාදනය හා නර්තනය යන ත්‍රිත්වයම එකවර ඉටු කරයි."),
        q("උඩරට 'පන්තේරු' නැටුමේදී පන්තේරුව අහසට දමා අල්ලා ගැනීම හා අත මත කරකැවීම හඳුන්වන්නේ කෙසේද?", "පන්තේරු හරඹ හෙවත් ශිල්ප දැක්වීම්", "අවුල්හැර සැරසීම", "බෙර අවදි කිරීම", "මණ්ඩි බිඳීම", "පන්තේරු වළල්ල කරකවමින් හා විසි කර අල්ලමින් නැට්ටුවා සිය දක්ෂතාව ප්‍රදර්ශනය කරයි."),
        q("උඩරට නර්තනයේදී ශිල්පියාගේ ගෙලෙහි පළඳින රිදී හෝ පිත්තල වටකුරු ආභරණය කුමක්ද?", "කරපටිය", "බුබුළු පටිය", "පා සළඹ", "තෝඩු", "සුදු හා රතු පසුබිම මත රිදී පටකින් ගෙල අලංකාර කරන ආභරණය කරපටියයි."),
        q("කොහොඹා කංකාරියේදී වෙස් නැට්ටුවන් විසින් ඉදිරිපත් කරන ප්‍රධාන පූජා නැටුම් පෙළපාලියක් කුමක්ද?", "යක් ඇනුම සහ කුවේණි අස්න", "සළු පාලිය සහ මරු සන්නිය", "ලෙනචිනා සහ ජසයා කෝලම", "පොල් කටු නැටුම", "කුවේණි අස්න, යක් ඇනුම සහ දන්වැට පාලිය කංකාරියේ වැදගත් කොටස් වේ."),
        q("උඩරට සරඹ පුහුණුවේදී පා සරඹ 12 අතර 'කැරකෙන' හා 'පැනුම්' චලන බහුලව එන්නේ කුමන සරඹ කොටස්වලද?", "අග පා සරඹ හෙවත් 9 සිට 12 දක්වා සරඹවල", "පළමු හා දෙවන පා සරඹවල පමණි", "තෙවන පා සරඹයේ පමණි", "පා සරඹ කිසිවක නොමැත", "පළමු සරඹවලින් පාද ස්ථාවර කර අවසන් සරඹවලින් වේගවත් කැරකිලි හා පැනුම් පුහුණු කරයි."),
        q("උඩරට නැටුමේදී දෙඅත් හිසට ඉහළින් ඔසවා මැණික් කටුවෙන් වක්‍ර කරන සම්ප්‍රදායික අත් ඉරියව්ව කුමක්ද?", "ලතා හස්තය හෙවත් උඩරට අත් මාරුව", "අංජලී හස්තය", "මුෂ්ටි හස්තය", "ත්‍රිශූල හස්තය", "දෑත් අඩ කවාකාරව කරකවමින් ගෙන යාම උඩරට නැටුමට අලංකාරයක් එක් කරයි."),
        q("වෙස් ඇඳුම පළඳින නැට්ටුවා 'දේවත්වයෙන්' හා මලය රජුගේ ස්වරූපයෙන් සලකන්නේ ඇයි?", "වෙස් තට්ටුව මලය රජුගේ රාජකීය කිරුළ සංකේතවත් කරන බැවිනි", "එය ඉතා බරින් අඩු නිසා", "ඕනෑම අවස්ථාවක එය බිම තබන නිසා", "කඩදාසිවලින් සාදා ඇති නිසා", "මලය රජුගේ ආභරණ 64 හි පූජනීය උරුමය ලෙස වෙස් ඇඳුම ගෞරවයෙන් සලකනු ලැබේ."),
        q("උඩරට නර්තනයේදී 'තීර්මානයක්' යන්නෙන් අදහස් කරන්නේ කුමක්ද?", "නැටුමේ එක් අදියරක් හෝ පද කොටසක් අවසන් කරන ත්‍රිත්ව තාල ඛණ්ඩය", "නැටුම ආරම්භ කිරීමට පෙර බිම වාඩිවීම", "වෙස් තට්ටුව ගලවා තැබීම", "ගැටබෙරය වාදනය නතර කිරීම", "පද කිහිපයක් වේගවත් රිද්මයකින් තුන් වරක් වාදනය කර නැවතීමෙන් තීර්මානය නිම කෙරේ."),
        q("උඩරට නැටුමේ 'කස්තිරම' යන තාක්ෂණික පදයෙන් හැඳින්වෙන්නේ කුමක්ද?", "වන්නමක හෝ නැටුමක අවසානයට යෙදෙන වේගවත් නැටුම් පද මාලාව", "වෙස් තට්ටුවේ රැඳි රිදී දම්වැල", "පාදයේ බඳින ගෙජ්ජි පටිය", "ගැටබෙරයේ වම් පැත්තේ හම", "වන්නම් කවිය නැටීමෙන් පසු ඉතා ජවසම්පන්නව ඉදිරිපත් කරන කොටස කස්තිරමයි."),
        q("උඩරට නර්තනයේදී 'අඩව්ව' යන්නෙහි නිවැරදි අර්ථය කුමක්ද?", "පිනුම්, කැරකිලි සහ සංකීර්ණ පාද හරඹ සහිත නැටුම් කොටස", "නැටුම ආරම්භයේ ගායනා කරන පූජා කවිය", "බෙර වාදකයාගේ ආසනය", "ඇඳුම් බඳින පටිය", "වන්නමක අවසන් භාගයේ කස්තිරමෙන් පසු උස පැනුම් සහිතව අඩව්ව ඉදිරිපත් කරයි."),
        q("වෙස් නැට්ටුවාගේ හිස පිටුපසින් ඉන දක්වා එල්ලා වැටෙන රිදී පටි හා රතු රෙදි කොටස හඳුන්වන්නේ කෙසේද?", "පිච්චමල් පටිය හෝ ජටා පටිය", "සිළම්බු", "හවඩිය", "බාහු වළලු", "හිස පිටුපසින් එල්ලා වැටෙන ජටා පටිය කැරකීමේදී චමත්කාර ලෙස විසිරී යයි."),
        q("උඩරට නර්තන සම්ප්‍රදායේදී 'තානම' ගායනා කරනු ලබන්නේ කුමන ස්වර හා අකුරු ඇසුරෙන්ද?", "තන තම් දන තනා වැනි ශබ්ද අකුරු ඇසුරෙන්", "ඉංග්‍රීසි හෝඩියේ අකුරු ඇසුරෙන්", "අත්පුඩි ශබ්දය පමණක් නැඟීමෙන්", "විදේශීය ගීත පද ඇසුරෙන්", "තේරුමක් නැති මිහිරි නාද අකුරු මගින් තානම ගයා නැටුමේ රිද්මය හා භාවය හඳුන්වා දෙයි."),
        q("උඩරට පන්තේරු නැටුමේ වාද්‍ය භාණ්ඩය වන පන්තේරුව නිපදවා ඇත්තේ කුමන ලෝහයකින්ද?", "පිත්තල හෝ ලෝකඩ", "වීදුරු", "මැටි", "රබර්", "වටකුරු පිත්තල රාමුවක කුඩා රිදී හෝ පිත්තල පෙති සවි කර පන්තේරුව සාදා ඇත."),
        q("උඩරට 'හවඩිය' යන ආභරණය වෙස් ඇඳුමේ කුමන ස්ථානයක පළඳිනු ලැබේද?", "ඉණ වටා ඉනහැඩය මත", "දකුණු කනේ", "නළල මත", "පාදයේ ඇඟිලිවල", "රිදී හෝ පිත්තල දම්වැලකින් සැදුම්ලත් හවඩිය ඉන අලංකාර කිරීමට යොදයි."),
        q("උඩරට සරඹ පුහුණු වන ශිෂ්‍යයාගේ දෘෂ්ටිය හෙවත් බැල්ම තිබිය යුත්තේ කුමන ආකාරයටද?", "කෙළින් ඉදිරියට හෝ අත් චලන දෙසට අවධානයෙන්", "නිතර බිම දෙස පමණක් බලාගෙන", "ඇස් තදින් පියාගෙන", "වහලය දෙසට හිස ඔසවාගෙන", "අත් ගිය තැනට ඇස් යෑම පෙරදිග නර්තනයේ ප්‍රධාන සිද්ධාන්තයකි."),
        q("උඩරට නැටුමේ 'පාය වදින' අවස්ථාවේදී පාදය පොළොවට තැබිය යුත්තේ කෙසේද?", "සම්පූර්ණ යටිපතුල හෝ විළුඹ තාලයට ස්පර්ශ වන සේ", "පාදයේ ඇඟිලි තුඩුවලින් පමණි", "දණහිස් බිම තබමින්", "දෙපා වාතයේ එල්ලා තබමින්", "මණ්ඩි ඉරියව්වේදී දෙපා පැතිවලට යොමු කර තාලයට සමබරව තැබීම අවශ්‍ය වේ."),
        q("උඩරට සම්ප්‍රදායේ 'දෙවොල් බාගය' හෝ 'මඟුල් බෙර' වාදනය සිදු කරන්නේ කුමන අවස්ථාවකදීද?", "ශාන්තිකර්ම හා නර්තන ආරම්භයේ ආශිර්වාද ගැනීමට", "නැටුම අවසන් වී ශාලාව වසන විට", "භෝජන සංග්‍රහයේදී පමණි", "පාසල් රැස්වීම අවසානයේදී", "තෙරුවන් හා දෙවියන් වෙනුවෙන් පළමුව මඟුල් බෙර වාදනය කිරීම සම්ප්‍රදායයි."),
        q("වෙස් නැට්ටුවාගේ ඉණේ රැඳි රතු සහ සුදු රෙදි කැබැලි හා දැති රැල්ල මගින් ඇති කරන ප්‍රධාන දෘශ්‍ය ප්‍රතිඵලය කුමක්ද?", "මණ්ඩි ඉරියව්ව හා කැරකිලි වඩාත් තේජස් ලෙස පෙන්වීම", "නැට්ටුවාගේ ගමන් වේගය අඩු කිරීම", "නැට්ටුවාගේ අත් සැඟවීම", "බෙර හඬ අඩු කිරීම", "මණ්ඩි නමන විට උළුදය හා රැළි මාලය අලංකාර ලෙස දිගහැරේ."),
        q("උඩරට සම්ප්‍රදායේ 'වෙස් ඇඳුම' කිලිටි වීමෙන් හා අගෞරවයෙන් වළක්වා ගැනීමට ගනු ලබන චාරිත්‍රය කුමක්ද?", "පිරිසිදු පෙට්ටියක ආරක්ෂිතව තබා පැළඳීමට පෙර වැඳ නමස්කාර කිරීම", "වතුරේ ගිල්වා තැබීම", "බිම අතුරා තැබීම", "සාමාන්‍ය ඇඳුම් සමඟ මිශ්‍ර කර දැමීම", "වෙස් ආභරණ පූජනීය වස්තු ලෙස සලකා වෙනම ආරක්ෂිතව තබා භාවිත කෙරේ."),
        q("උඩරට නැටුමේදී දකුණු පාදය ඉදිරියට තබා වම් පාදය පසුපසින් ගෙන හැරෙන විශේෂිත ගමන් පියවර හඳුන්වන්නේ කෙසේද?", "ගමන් තාලය හෙවත් චාරි පියවර", "සන්නි පැනුම", "ගිරා පියවර", "කෝලම් ඇවිදීම", "එක් තැනක සිට තවත් තැනකට තාලයට ගමන් කිරීමට ගමන් පද යොදා ගනී."),
        q("උඩරට නර්තන ශිල්පියා පුහුණු වන 'බඹර කැරකිල්ල' යන්නෙන් අදහස් කරන්නේ කුමක්ද?", "වළල්ලක් මෙන් වේගයෙන් එකම අක්ෂයක කැරකීම", "බිම දිගා වී පෙරළීම", "පසුපසට ඇවිද යාම", "දෙපා බැඳ සිටගැනීම", "බඹරයක් මෙන් තනි කකුලෙන් හෝ දෙපයින් සමබරව වේගයෙන් කැරකීම නර්තන දක්ෂතාවකි."),
        q("උඩරට පා සරඹ පුහුණුවේදී ශිෂ්‍යයාට 'පළමු මණ්ඩිය' තැබීමට උපදෙස් දෙන්නේ කෙසේද?", "දෙපා අතර පරතරය වියතක් පමණ තබා දණහිස් දෙපසට යොමු කර නැමීම", "දෙපා සම්පූර්ණයෙන් එකට ඈඳා කෙළින් සිටීම", "එක් කකුලක් පමණක් බිම තැබීම", "වළලුකර දෙක ගැටගසා සිටීම", "මණ්ඩියේදී කඳ කෙළින් තබා උරහිස් සමබර කර ගැනීම අනිවාර්ය වේ."),
        q("උඩරට සම්ප්‍රදායේ 'වට්ටම් අඩව්ව' යනු කුමක්ද?", "සම්පූර්ණ වටයක් කැරකෙමින් හා පනිමින් ඉදිරිපත් කරන අවසාන අඩව් කොටස", "තානම ගැයීමට පෙර බෙර වාදනය ආරම්භ කරන මූලික තාල කොටස", "නැටුම අතරතුර හිසේ පැළඳි වෙස් තට්ටුව බිම තබා වඳින අවස්ථාව", "දෑතේ ඇති තාලම්පට අතින් අත මාරු කරමින් නිහඬව සිටින කොටස", "ප්‍රේක්ෂක අවධානය උපරිමයට ගන්නා අවසාන ජවසම්පන්න නැටුම මෙයයි."),
        q("උඩරට නර්තනයේ 'ගොඩ සරඹ' අභ්‍යාස මාලාව ආරම්භ කිරීමට පෙර සිසුන් සිදු කරන නමස්කාර පදය කුමක්ද?", "ආයුබෝවන් කීම හා සුරත් නමස්කාරය", "පසුපස හැරී යාම", "අත්පුඩි ගැසීම", "උස් හඬින් කෑගැසීම", "භූමියට, ගුරුන්ට හා ප්‍රේක්ෂකයන්ට වැඳ නමස්කාර කිරීම නර්තන සදාචාරයයි."),
        q("උඩරට වෙස් ඇඳුමේ පහළ කොටසට යොදන 'හඟල' නමින් හඳුන්වන කොටස කුමක්ද?", "ඉණට බඳින අලංකාර රතු සහ සුදු රැළි රෙදි කට්ටලය", "හිසේ පළඳින රිදී පටිය", "අත්වල දමන වළලු", "බෙරයේ වරපටිය", "හඟල නැටුමේදී අලංකාර ලෙස විසිරී යන සේ රැළි කර සකසා ඇත."),
        q("උඩරට සම්ප්‍රදායේ 'අත සේදීමේ සරඹය' හෝ 'මණ්ඩි අත් මාරුව' ඉගැන්වෙන්නේ කුමන අදියරේදීද?", "ගොඩ සරඹ පුහුණු අදියරේදී", "වෙස් මංගල්‍යයෙන් පසු පමණි", "සන්නි නැටුම් අදියරේදී", "කෝලම් අදියරේදී", "ගොඩ සරඹවලදී දෙඅත් හිස මට්ටමින් හා උරහිස් මට්ටමින් ලැසි ලෙස හැසිරවීම උගන්වයි."),
        q("උඩරට නැට්ටුවෙකු සිය නැටුම අතරතුර 'ඉහළ පිනුම්' හෙවත් 'බඹර පිනුම්' ගැසීමෙන් ප්‍රදර්ශනය කරන්නේ කුමක්ද?", "ශාරීරික ශක්තිය, ජවය හා සමබරතාව", "විඩාවට පත් වූ බව", "තාලය වැරදුණු බව", "වාද්‍ය භාණ්ඩ බිඳුණු බව", "අවකාශයේ පාවී යන ආකාරයෙන් පැන නැවත මණ්ඩි ඉරියව්වට පැමිණීම ඉහළ කුසලතාවකි."),
        q("උඩරට නැටුම් කලාවේදී 'සුරල් පද' යනුවෙන් හඳුන්වන්නේ කුමක්ද?", "බෙර වාදනයේදී හා නැටුමේදී වේගයෙන් ගලපා ගන්නා අලංකාර පද රටා", "සෙමින් හුස්ම ගන්නා ක්‍රමය", "හිස්වැසුම් ගලවන ක්‍රමය", "පාවහන් පළඳින ක්‍රමය", "ගැටබෙර වාදකයා හා නැට්ටුවා අතර මනා සංවාදයක් සුරල් පද මඟින් ඇති වේ."),
        q("උඩරට 'සළු නැටුම' හෝ 'චාමර නැටුම' ඉදිරිපත් කිරීමේදී ශිල්පීන් දෙඅතින් ගන්නා උපකරණ මොනවාද?", "සුදු හෝ වර්ණවත් රෙදි පටි සහ සුදු චාමර", "මැටි කළ සහ පොල් කටු", "වේවැල් කුලු සහ මෝල්ගස්", "යක් බෙර සහ කස", "සුදු සේද රෙදි පටි සහ චාමර සුළඟේ පාවෙමින් මනරම් දසුනක් මවයි."),
        q("වෙස් කට්ටලයේ පළඳින 'දෙවුර මාලය' හෙවත් උරබාහු ආභරණය මගින් ආවරණය කරනු ලබන ශරීර කොටස කුමක්ද?", "උරහිස් සහ උඩු බාහු ප්‍රදේශය", "දණහිස් ප්‍රදේශය", "වළලුකර ප්‍රදේශය", "හිස් මුදුන", "වෙස් ඇඳුමේ උඩුකය ආභරණ උරහිස් හා පපුව පුරා රන් රිදී පැහැයෙන් දිදුලයි."),
        q("උඩරට නර්තන සම්ප්‍රදායේ 'වන්නම්' හැරුණු විට නැට්ටුවාගේ කුසලතාව මැන බලන අනෙක් ප්‍රධාන කොටස කුමක්ද?", "සන්දර්ශන අඩව් සහ හරඹ කොටස්", "මුළුමනින්ම නිශ්චලව සිටීම", "බිම හිඳ කවි කියවීම", "පසුබිම් තිර අඳින අයුරු", "විවිධ ශාන්තිකර්ම අඩව් හා බෙර පද අනුව ක්ෂණිකව නැටීම දක්ෂතාව මනින මිනුමකි."),
        q("උඩරට නැටුමේදී ශිල්පියාගේ හිස සෙලවීම හෙවත් 'ග්‍රීවා හා ශිරෝ චලන' සිදු කරන්නේ කුමන රීතියකට අනුවද?", "තාලයට හා භාවයට ගැළපෙන සංයමයෙන් යුතුව", "හිතූ පරිදි වේගයෙන් පැද්දෙමින්", "කිසිසේත් හිස නොසොල්වා තද කරගෙන", "පිටුපසට පමණක් හරවාගෙන", "සියුම් බෙල්ලේ හා හිසේ චලන නැටුමේ ජීව ගුණය වැඩි කරයි."),
        q("උඩරට පා සරඹ පුහුණුවේදී ශිෂ්‍යයා 'වම්' සහ 'දකුණු' පැති සමානව පුහුණු කළ යුත්තේ ඇයි?", "සිරුරේ දෙපැත්තේම සමමිතිය හා සමබරතාව පවත්වා ගැනීමට", "දකුණු පැත්ත පමණක් වෙහෙස කිරීමට", "එක් කකුලක් පමණක් භාවිත කිරීමට", "ප්‍රේක්ෂකයන් රැවටීමට", "සමබර පුහුණුවක් නොලැබුණහොත් නැටුමේදී එක් පැත්තකට ඇදවීම සිදු වේ."),
        q("උඩරට නැටුමේ 'පන්තේරු' නැටුමට අදාළ ප්‍රධාන පුරාවෘත්තය සම්බන්ධ වන්නේ කුමන රජ දවසටද?", "පඬුවස්දෙව් හෝ කීර්ති ශ්‍රී රාජසිංහ රජ දවසට", "වික්ටෝරියා රැජිනගේ සමයට", "ලන්දේසි ආණ්ඩුකාර සමයට", "නූතන යුගයට", "දේව පූජා හා රාජ සභා නැටුම් ලෙස පන්තේරු නැටුම පැරණි රාජ සමයන්හි සිට පැවත එයි."),
        q("උඩරට සම්ප්‍රදායේ 'වෙස් ඇඳුම' සම්පූර්ණ වීමට අත්‍යවශ්‍ය වන හිස් ආභරණය හඳුන්වන පොදු නම කුමක්ද?", "වෙස් තට්ටුව", "තෙල්මේ තොප්පිය", "සන්නි මුහුණ", "කෝලම් තොප්පිය", "සිළුමිණ, පත් හා නළල් පටිය එක්ව සැකසුණු විචිත්‍ර හිස් පළඳනාව වෙස් තට්ටුව නම් වේ."),
        q("උඩරට නර්තන පුහුණු කාලයේදී 'තාත් තාත් තොං තොං' ලෙස මුවින් පද කීම හඳුන්වන්නේ කුමන නමකින්ද?", "වචන සරඹ හෙවත් මුඛ සරඹ", "ගීත රචනය", "නාට්‍ය දෙබස්", "පත්තිනි යාතිකාව", "දෑත් පාද චලන සමඟ මුවින් තාල පද කීමෙන් තාල අවබෝධය ස්ථිර වේ."),
        q("උඩරට නැටුමේදී 'ගැටබෙර වාදකයා' සහ 'නැට්ටුවා' අතර පැවතිය යුතු ප්‍රධානම සම්බන්ධතාව කුමක්ද?", "අන්‍යොන්‍ය අවබෝධය හා එකම ලයකින් ගමන් කිරීම", "එකිනෙකා දෙස නොබලා වෙනස් වේගවලින් යාම", "නැට්ටුවා බෙරකරුට පිටුපා ඉවත්ව යාම", "වාදකයා කතා කරමින් නැවැත්වීම", "බෙර හඬේ ක්ෂණික වෙනස්වීම් නැට්ටුවාගේ පියවර සමඟ මනාව ගැළපිය යුතුය."),
        q("උඩරට නර්තන සම්ප්‍රදායේ කාන්තා ශිල්පිනියන් සාමාන්‍යයෙන් පුහුණු වන මූලික ඉරියව්ව උඩරට පිරිමි මණ්ඩියෙන් වෙනස් වන්නේ කෙසේද?", "වඩාත් මෘදු හා මධ්‍යස්ථ දණහිස් නැවීමකින් යුක්ත වීම", "කිසිදු දණහිස් නැවීමක් නොමැති වීම", "වෙස් තට්ටුව පැළඳ නැටීම", "බිම හිඳගෙන නැටීම", "කාන්තා නර්තනයේ ලැසි ගුණය ආරක්ෂා කිරීමට සමබර මධ්‍යස්ථ මණ්ඩිය භාවිත කෙරේ."),
        q("උඩරට නැටුම් කලායතනවල පළමු පාඩම ලෙස බොහෝ විට උගන්වනු ලබන්නේ කුමන ක්‍රියාකාරකමද?", "පොළොවට හා ගුරුන්ට වැඳ නමස්කාර කොට පළමු මණ්ඩිය තැබීම", "වන්නම් 18 එක දිනකින් නැටීම", "ගිනි පෑගීම පුහුණු වීම", "කෝලම් නැටුම් රඟපෑම", "නිවැරදි මණ්ඩි ඉරියව්ව සකසා ගැනීම මුළු පුහුණුවේම අත්තිවාරම වේ."),
        q("උඩරට වෙස් ඇඳුමේ පහළ කොටසේ ඇති සුදු රෙද්දේ උල් හැඩැති රැළි මාලාව නිසි ලෙස සකස් කිරීම හඳුන්වන්නේ කෙසේද?", "හඟල නැමීම හෙවත් කච්ච ගැසීම", "අවුල්හැර ගෙතීම", "සිළම්බු ලෑම", "බුබුළු බැඳීම", "වෙස් ඇඳුම ඇඳීම විශේෂ කලාත්මක පුහුණුවක් ඇති පුද්ගලයෙකු විසින් සිදු කළ යුතු කාර්යයකි."),
        q("උඩරට පා සරඹ අතර 'දෙවන' හා 'තෙවන' පා සරඹ පුහුණුවීමේදී වර්ධනය වන ප්‍රධානම ශාරීරික කුසලතාව කුමක්ද?", "පාද මාරු කිරීමේ නිරවද්‍යතාව හා මණ්ඩි ස්ථාවරත්වය", "හිස කරකැවීමේ වේගය", "දෑස් වසා සිටීමේ හැකියාව", "කටහඬේ උස් පහත් බව", "මූලික පා සරඹවලින් දෙපා හා දණහිස් නිවැරදි තාලයට පුරුදු කෙරේ."),
        q("උඩරට නර්තනයේ 'ගොඩ සරඹ' අභ්‍යාසවලදී අත් චලන සිදු කරන අවකාශ පරාසය කුමක්ද?", "ශරීරය දෙපස අඩ කවාකාරව උරහිස් හා හිස මට්ටම තුළ", "දණහිස් අතර පටු ප්‍රදේශයේ", "පිටුපස කොන්දට පිටතින්", "පොළොවේ අතුරා ඇති පැදුර මත", "උඩරට නර්තන අත් චලන ශරීරය වටා තේජස් වෘත්තාකාර රේඛා මවයි."),
        q("උඩරට වෙස් තට්ටුවේ ඇති 'ජටාව' නමැති කොටස සෑදීමට ප්‍රධාන වශයෙන් භාවිත කරන රෙදි පැහැය කුමක්ද?", "සුදු පැහැති සිහින් රෙදි", "තද කොළ පැහැති රෙදි", "කහ පැහැති සිල්ක් රෙදි", "අළු පැහැති රළු රෙදි", "සුදු ජටාව හිස වටා බැඳ එය මත රිදී ශිඛා බන්ධනය හා පත් සවි කරනු ලැබේ."),
        q("උඩරට 'නෛයන්ඩි' නැටුමේදී නැට්ටුවා හිසේ පළඳිනු ලබන විශේෂ හිස් වැසුම කුමක්ද?", "සුදු ජටාව හෙවත් තලප්පාව", "සිළුමිණ සහිත වෙස් තට්ටුව", "රතු තෙල්මේ තොප්පිය", "කෝලම් රජ ඔටුන්න", "වෙස් බැඳීමට පෙර සුදු ජටාවක් හිසේ බැඳ නෛයන්ඩි නැටීම සිරිතකි."),
        q("උඩරට 'උඩැක්කි' නැටුම සාමාන්‍යයෙන් කණ්ඩායමක් ලෙස ඉදිරිපත් කිරීමේදී නැට්ටුවන් අනුගමනය කරන සුවිශේෂී ක්‍රමය කුමක්ද?", "කවි හුවමාරු කර ගනිමින් යුගල හෝ පෙළට නැටීම", "මුළු කාලයම බිම වැතිරී සිටීම", "ගැටබෙර දෙකක් කරේ එල්ලා ගැනීම", "කිසිදු ශබ්දයක් නොනඟා නැටීම", "එක් අයෙකු කවිය ගයද්දී අනෙකා උඩැක්කිය වයමින් පිළිතුරු කවිය නැටීම සිදු වේ."),
        q("උඩරට නැටුමේ 'පන්තේරුව' වාද්‍ය භාණ්ඩය අයත් වන්නේ පංචතූර්ය වර්ගීකරණයේ කුමන කොටසටද?", "ඝන වාද්‍ය භාණ්ඩ ගණයට", "සුසිර වාද්‍ය භාණ්ඩ ගණයට", "ආතත වාද්‍ය භාණ්ඩ ගණයට", "විතත වාද්‍ය භාණ්ඩ ගණයට", "පිත්තල රාමුව හා පිත්තල පෙති එකිනෙක ගැටීමෙන් නාද උපදින බැවින් පන්තේරුව ඝන භාණ්ඩයකි."),
        q("උඩරට වෙස් ඇඳුමේ 'ඉනහැඩය' මත සවි කර ඇති කුඩා රිදී පටි හා මෝස්තර මගින් ඉටු වන ප්‍රධාන කාර්යය කුමක්ද?", "ඉණෙහි ඇඳි රැළි මාලය ශක්තිමත්ව රඳවා අලංකාර කිරීම", "හිස කෙස් ආවරණය කිරීම", "උගුර ආරක්ෂා කිරීම", "පාදවල වේගය අඩු කිරීම", "ඉනහැඩය ඉනට තදින් බැඳීම නිසා පැනුම්වලදී පහළ ඇඳුම නොගැලවී පවතී."),
        q("උඩරට නර්තන සම්ප්‍රදායේ 'කරපටිය' පළඳින නැට්ටුවා එය සකස් කරන්නේ ඇඟේ කුමන කොටසකටද?", "ගෙල හා උරහිස අතර කොටසට", "දණහිස් මතට", "වළලුකර වටා", "මැණික් කටුව මතට", "ගෙල වටා පළඳින රිදී හා පබළු මිශ්‍ර කරපටිය වෙස් ඇඳුමට ගාම්භීර පෙනුමක් එක් කරයි."),
        q("උඩරට සම්ප්‍රදායේ 'වන්නමක්' ඉදිරිපත් කිරීමේදී පළමුවෙන්ම ගායනා කරනු ලබන කොටස කුමක්ද?", "තානම", "කස්තිරම", "අඩව්ව", "සීරුමාරුව", "තානම මගින් අදාළ වන්නමේ තාලය, රිද්මය හා ලය හඳුන්වා දෙනු ලැබේ."),
        q("උඩරට නැටුමේදී 'තානම' සහ 'කවිය' අවසන් වූ පසු නැට්ටුවා ඊළඟට පිවිසෙන කොටස කුමක්ද?", "සීරුමාරුව හා කස්තිරම", "නින්දට යාම", "සභාවෙන් පිටවීම", "පා සරඹ පළමු පාඩම", "කවියේ අදහස අභිනයෙන් දැක්වීමෙන් පසු කස්තිරම නැටීම සිදු කෙරේ."),
        q("උඩරට වෙස් නැට්ටුවාගේ 'නළල් පටිය' සහ 'තෝඩු' අතර ඇති සම්බන්ධතාව කුමක්ද?", "නළල් පටිය කෙළවරින් කන් දෙක දෙසට තෝඩු එල්ලා තිබීම", "දෙකම පාදවල පැළඳීම", "දෙකම ඉණෙහි බැඳීම", "තෝඩු බෙරයේ සවි කිරීම", "මෙම හිස් ආභරණ එක්ව හිසට අලංකාර රාජකීය රාමුවක් නිර්මාණය කරයි."),
        q("උඩරට නර්තන පුහුණුවේදී ශිෂ්‍යයෙකු 'මණ්ඩිය' නමා සිටින විට කොඳු ඇට පෙළ තබා ගත යුතු ආකාරය කුමක්ද?", "පොළොවට ලම්බකව සෘජුව හා කෙළින්", "ඉදිරියට සම්පූර්ණයෙන් නමාගෙන", "පිටුපසට ඇල වීගෙන", "වම් පැත්තට ඇද වීගෙන", "කඳ සෘජුව තැබීමෙන් උඩරට නර්තනයේ උසස් සෘජු චලන ලක්ෂණය රැකේ."),
        q("උඩරට පා සරඹ 12 අතරින් 'වම්' පාදය සහ 'දකුණු' පාදය මාරුවෙන් මාරුවට පසුපසට හා ඉදිරියට තබා පුහුණු වන්නේ ඇයි?", "ඕනෑම දිශාවකට තාලයට ගමන් කිරීමට", "වේදිකාවෙන් ඉවතට පැන දිව යාමට", "බෙර වාදකයාට පිටුපා ඉවත් වීමට", "තාලය නොසලකා එකම තැන රැඳීමට", "සෑම දිශාවකටම තාලයට ගමන් කිරීම සඳහා පාද විනය අත්‍යවශ්‍ය වේ."),
        q("උඩරට සම්ප්‍රදායේ 'මඟුල් බෙර' වාදනය ආරම්භ වන්නේ කුමන ආශිර්වාදාත්මක අරමුණක් පෙරදැරි කරගෙනද?", "සියලු බාධක දුරු වී කලා කටයුත්ත සාර්ථක වීම පැතීමට", "ප්‍රේක්ෂකයන්ට පිටව යන ලෙස දැන්වීමට", "තරගයක පරාජය ප්‍රකාශ කිරීමට", "නැටුම අවසන් කිරීමට", "දේව ආශිර්වාදය හා තෙරුවන් ගුණ සිහි කරමින් සෑම උත්සවයක්ම මඟුල් බෙරයෙන් ඇරඹේ."),
        q("උඩරට වෙස් ඇඳුමේ 'අවුල්හැරය' නිර්මාණය කර ඇති ප්‍රධාන ද්‍රව්‍යය කුමක්ද?", "විවිධ වර්ණ වීදුරු හෝ සුදු පබළු", "ලී කැබලි", "පොල් කටු", "මැටි බෝල", "කුඩා පබළු දැලක් මෙන් ගෙතූ අවුල්හැරය රිදී බොත්තම් හා පදක්කම සමඟ උඩුකයට පළඳියි."),
        q("උඩරට නැටුමේදී ශිල්පියාගේ දණහිස් දෙක දෙපසට විහිදා තැබීමෙන් ඇති වන ප්‍රධාන වාසිය කුමක්ද?", "පහළ සිරුරට පළල් හා ශක්තිමත් ආධාරකයක් ලැබීම", "පහසුවෙන් බිම වැටීම", "කෙටි කලකින් මහන්සි වීම", "ඇවිදීම අපහසු වීම", "පළල් මණ්ඩිය චලන වේගවත් කිරීමේදී හා පැනුම්වලදී සමබරතාව සුරකියි."),
        q("උඩරට නර්තන කලාවේදී 'ගැටබෙරයේ වම් ඇස' වැයීමේදී ලැබෙන නාද ස්වභාවය කුමක්ද?", "ගැඹුරු හා අනුනාදී බර හඬක්", "තියුණු හා කෙටි උස් හඬක්", "වීදුරු බිඳෙන හඬක්", "සීනු නාදයක්", "හරක් සමින් ආවරණය කළ වම් ඇසෙන් 'දොං', 'ධිං' වැනි ගැඹුරු නාද උපදී."),
        q("උඩරට නැටුමේ 'තීර්මාන' පදයක් වාදනය කිරීමේදී නැට්ටුවා විසින් තබන පාද පියවරවල ස්වභාවය කුමක්ද?", "වේගවත්ව පද ගලපා නැවතීමෙන් තාලය අවධාරණය කිරීම", "ඉතා සෙමින් ඇවිදීම", "පාද බිමින් නොඑසවීම", "බිම දිගා වීම", "බෙර පදයට අනුරූපව පාද හා දෑත් එක්ව ක්‍රියා කොට තීර්මානය නිම කෙරේ."),
        q("උඩරට සම්ප්‍රදායේ 'වෙස් ඇඳුම' පැළඳීමට නුසුදුසු අපිරිසිදු අවස්ථාවක් ලෙස සැලකෙන්නේ කුමක්ද?", "වන්දනා හා ශාන්තිකර්ම විනයට පටහැනිව අගෞරවනීය ස්ථානවල පැළඳීම", "විහාර පෙරහැරේ පැළඳීම", "කොහොඹා කංකාරියේ පැළඳීම", "ප්‍රසිද්ධ සංස්කෘතික උත්සවයේ පැළඳීම", "වෙස් ඇඳුමේ පූජනීය ගෞරවය සැමවිටම ආරක්ෂා කළ යුතුය."),
        q("උඩරට 'නෛයන්ඩි' නැටුමේදී නැට්ටුවා පළඳින උඩුකය ආභරණ මොනවාද?", "කෙටි අවුල්හැරයක් හා පබළු මාල, බාහු වළලු", "විශාල රිදී වෙස් තට්ටුව", "කෝලම් ලී මුහුණ", "පිදුරු තොප්පිය", "වෙස් ඇඳුමට වඩා සැහැල්ලු ආභරණ කට්ටලයක් නෛයන්ඩි සඳහා යොදයි."),
        q("උඩරට නර්තන පුහුණුවේදී 'දණ්ඩියම් කඳ' භාවිත කිරීම නතර කරන්නේ කවදාද?", "පා සරඹ 12 ස්ථාවරව හා සමබරව නැටීමට හැකි වූ පසු", "පළමු දිනයේ විනාඩි පහකට පසු", "කිසිදා නතර නොකරයි", "වෙස් මංගල්‍යයෙන් වසර දහයකට පසු", "ආධාරකයකින් තොරව මණ්ඩි සමබරතාව රැකගත හැකි වූ විට ගොඩ සරඹවලට යොමු කෙරේ."),
        q("උඩරට සම්ප්‍රදායේ 'කඩු හරඹ' හෝ 'සළු නැටුම' වැඩි වශයෙන්ම පෙන්වන චලන ගුණය කුමක්ද?", "දෑත්වල නම්‍යශීලී පාලනය හා වේගවත් කැරකිලි", "බිම වාඩි වී ගායනය", "නිහඬව සිටගෙන සිටීම", "හිස පහත් කරගෙන සිටීම", "උපකරණ හසුරුවමින් සිරුරේ සමබරතාව පෙන්වීම මෙහි විශේෂත්වයයි."),
        q("උඩරට වෙස් කට්ටලයේ 'උර බාහු' අලංකාර කරන රිදී පළඳනාව හඳුන්වන්නේ කුමන නමකින්ද?", "කයිමෙත්ත හෙවත් බාහු වළලු", "සිළම්බු", "ජටා පටිය", "උළුදය", "දඟර ගැසුණු රිදී හෝ පිත්තල ආභරණය උඩු බාහුවේ තදින් සවි කෙරේ."),
        q("උඩරට නැටුමේ 'පාද චලන' හා 'අත් චලන' අතර ඇතිවිය යුතු මූලික රිද්ම සබඳතාව කුමක්ද?", "දෙපා පොළොවේ වදින තාලයට අනුරූපව දෙඅත් චලනය සමපාත වීම", "අත් එක තාලයකටත් පා වෙනත් තාලයකටත් යාම", "අත් සොලවන විට පාද ගල් ගැසී තිබීම", "පාද චලනයේදී අත් සාක්කුවේ තැබීම", "අංග සම්පූර්ණ නර්තනයක් සඳහා අත් හා පාද චලන එකම රිද්මයකින් බැඳිය යුතුය."),
        q("උඩරට නැටුමේදී 'ගමන් පදය' භාවිත කරන්නේ කුමන ප්‍රායෝගික අවශ්‍යතාව සඳහාද?", "පෙරහැරේ හෝ වේදිකාවේ එක් තැනක සිට තවත් තැනකට තාලයට ගමන් කිරීමට", "නැටුම අවසන් කර පුටුවේ හිඳ ගැනීමට", "වතුර පානය කිරීමට", "බෙරය මාරු කිරීමට", "පෙරහැර ගමනේදී මෙන්ම වේදිකා ස්ථාන මාරුවීම්වලදී ගමන් තාල යොදා ගනී."),
        q("උඩරට සම්ප්‍රදායේ 'වෙස් බැඳීමේ'දී ගුරුවරයා විසින් ශිෂ්‍යයාගේ හිස මත තබන පූජනීය පළඳනාව කුමක්ද?", "සිළුමිණ හා නළල් පටිය සහිත වෙස් තට්ටුව", "පොල් කොළ තොප්පිය", "රබන් රාමුව", "සළු පාලි මුහුණ", "මෙම මොහොත ශිෂ්‍යයාගේ කලා දිවියේ උත්තරීතර අවස්ථාව ලෙස සැලකේ."),
        q("උඩරට නැටුම් ක්ෂේත්‍රයේදී 'පන්තේරු' නැට්ටුවන් සාමාන්‍යයෙන් පළඳින හිස් ආවරණය කුමක්ද?", "වෙස් තට්ටුව හෝ සුදු පැහැති ජටාව", "රතු පැහැති කෝලම් තොප්පිය", "සන්නි මුහුණ", "කිසිදු රෙද්දක් නොමැතිව හිස බූ ගෑම", "අවස්ථාව අනුව වෙස් ඇඳුමින් හෝ නෛයන්ඩි ඇඳුමින් පන්තේරු නැටුම ඉදිරිපත් කරයි."),
        q("උඩරට නර්තනයේ 'සරඹ පුහුණුව' අවසන් කළ ශිෂ්‍යයෙකුට ඊළඟට ලබා දෙන ප්‍රධාන පාඩම් කොටස කුමක්ද?", "සරල කෙටි අඩව් හා මූලික වන්නම්", "රාජ්‍ය පාලන නීති", "සන්නි වෙස්මුහුණු කැපීම", "බටහිර ඔපෙරා ගායනය", "සරඹවලින් ලද ශාරීරික පාලනය උපයෝගී කරගෙන වන්නම් නැටීම අරඹයි."),
        q("උඩරට 'ගැටබෙරයේ දකුණු ඇස' සකස් කර ඇති සත්ව සම කුමක්ද?", "රීළවා හෙවත් වඳුරු සම", "හරක් සම", "එළු සම", "තලගොයි සම", "වඳුරු සම තුනී බැවින් 'තත්', 'ජිත්' වැනි තියුණු නාද දකුණු ඇසෙන් ලැබේ."),
        q("උඩරට 'ගැටබෙරයේ වම් ඇස' සකස් කර ඇති සත්ව සම කුමක්ද?", "හරක් හෙවත් ගව සම", "වඳුරු සම", "කුකුළු සම", "මත්ස්‍ය සම", "ඝන ගව සම නිසා වම් ඇසෙන් ගැඹුරු 'දොං' නාදය නිපදවේ."),
        q("උඩරට නැට්ටුවා 'බිමට නැමී වම් හා දකුණු අත්ල පොළොවට තබා නැවත නැඟිටින' පුහුණු අංගයෙන් වර්ධනය වන්නේ කුමක්ද?", "තුනටිය හා කොඳු ඇට පෙළෙහි නම්‍යශීලී බව", "දත්වල ශක්තිය", "නියපොතුවල දිග", "කන් ඇසීම", "භූමි නමස්කාරය හා වන්නම් කස්තිරම් සඳහා මෙම නම්‍යශීලී පුහුණුව උපකාරී වේ."),
        q("උඩරට නර්තනයේදී 'මණ්ඩිය' මට්ටම් තුනෙන් පොළොවට වඩාත්ම පහත් වූ ඉරියව්ව හඳුන්වන්නේ කෙසේද?", "යටි මණ්ඩිය හෙවත් පහත් මණ්ඩිය", "උඩු මණ්ඩිය", "සම මණ්ඩිය", "අහස් මණ්ඩිය", "උස්, මධ්‍යම හා පහත් මණ්ඩි වශයෙන් නැටුමේ ගැඹුර වෙනස් කර දක්වයි."),
        q("උඩරට නැටුමේදී 'ගොඩ සරඹ' අතරින් ශරීරය දෙපසට ඇල කරන චලන සිදු කරන්නේ කුමන ශරීර අවයවය කේන්ද්‍ර කරගෙනද?", "ඉණ හෙවත් කටී ප්‍රදේශය", "දකුණු මහපටැඟිල්ල", "නාසය", "වම් කන", "ඉණෙන් උඩ කොටස ක්‍රමානුකූලව නමා චලනය කිරීමෙන් නැටුමට අලංකාර රේඛා ලැබේ."),
        q("උඩරට නර්තන සම්ප්‍රදාය පිළිබඳව ඉගෙන ගන්නා ශිෂ්‍යයෙකු 'වෙස් ඇඳුම' ගැන දැනගත යුතු වැදගත්ම ඓතිහාසික කරුණ කුමක්ද?", "මලය රජුගේ සූසැට ආභරණ සංකේතවත් කරන පූජනීය කලා උරුමයක් බව", "එය බටහිර වේදිකා නාට්‍යයෙන් ගත් බව", "එය පහතරට සන්නි ඇඳුමක් බව", "එය යුද සෙබළුන්ගේ සන්නාහයක් බව", "ශාන්තිකර්ම පුරාවෘත්තය හා රාජකීය අනන්‍යතාව වෙස් ඇඳුම තුළ ගැබ්ව ඇත.")
    )
}

